CREATE TABLE users(id SERIAL PRIMARY KEY,username VARCHAR(80) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role VARCHAR(20) NOT NULL);
CREATE TABLE customers(id SERIAL PRIMARY KEY,name VARCHAR(160) NOT NULL,state VARCHAR(80) NOT NULL);
CREATE TABLE products(id SERIAL PRIMARY KEY,name VARCHAR(160) NOT NULL,price NUMERIC(12,2),gst NUMERIC(5,2));
CREATE TABLE items(id SERIAL PRIMARY KEY,name VARCHAR(160) UNIQUE,category VARCHAR(30),unit VARCHAR(20));
CREATE TABLE movements(id SERIAL PRIMARY KEY,item_id INT REFERENCES items(id),delta NUMERIC(14,3),source VARCHAR(100));
CREATE TABLE orders(id SERIAL PRIMARY KEY,customer_id INT REFERENCES customers(id),salesman_id INT REFERENCES users(id),qty INT,status VARCHAR(30),shortage INT DEFAULT 0);
CREATE TABLE runs(id SERIAL PRIMARY KEY,expected INT,actual INT,yield_variance NUMERIC(8,3),oil_variance NUMERIC(8,3));
CREATE TABLE invoices(id SERIAL PRIMARY KEY,order_id INT UNIQUE REFERENCES orders(id),taxable NUMERIC(12,2),cgst NUMERIC(12,2),sgst NUMERIC(12,2),igst NUMERIC(12,2),total NUMERIC(12,2),paid NUMERIC(12,2),dispatched BOOLEAN DEFAULT FALSE);
CREATE TABLE payments(id SERIAL PRIMARY KEY,invoice_id INT REFERENCES invoices(id),amount NUMERIC(12,2));
CREATE TABLE costs(id SERIAL PRIMARY KEY,run_id INT REFERENCES runs(id),labour NUMERIC(12,2),utilities NUMERIC(12,2));
